<?php $id=(int)($_GET['id']??0);$employee=foundation_employee($pdo,$id);if(!$employee){echo '<div class="alert error">Employee not found.</div>';return;}$q=$pdo->prepare("SELECT id FROM hr_media WHERE user_id=? AND purpose='profile' LIMIT 1");$q->execute([$id]);$photo=$q->fetchColumn();$tab=(string)($_GET['tab']??'overview');if(!in_array($tab,['overview','employment','documents'],true))$tab='overview';?>
<section class="card profile-banner"><?php if($photo):?><img class="avatar large photo" src="media.php?employee=<?=$id?>" alt=""><?php else:?><span class="avatar large"><?=h(substr($employee['first_name'],0,1).substr($employee['last_name'],0,1))?></span><?php endif;?><div class="grow"><h2><?=h($employee['name'])?></h2><p class="hint"><?=h(($employee['designation_name']?:'Designation not assigned').' · '.($employee['department_name']?:'Department not assigned'))?></p><p class="hint"><?=h($employee['employee_code']?:'Employee ID not assigned')?></p></div><?php fbadge($employee['employment_status'],$employee['employment_status']==='Active');if(can($pdo,$user,'employees.edit')):?><a class="button" href="?page=employee-edit&id=<?=$id?>">Edit employee</a><?php endif;?></section>
<nav class="tabs" aria-label="Employee profile"><?php foreach(['overview'=>'Overview','employment'=>'Employment','documents'=>'Documents'] as $t=>$label):if($t==='documents'&&!can($pdo,$user,'documents.view'))continue;?><a href="?page=employee-view&id=<?=$id?>&tab=<?=$t?>" <?=$tab===$t?'aria-current="page"':''?>><?=$label?></a><?php endforeach;?></nav>
<?php if($tab==='overview'||$tab==='employment'):
$fields=$tab==='overview'?['username'=>'Username','email'=>'Work email','personal_email'=>'Personal email','mobile'=>'Mobile number','alternate_phone'=>'Alternate phone','birth_date'=>'Date of birth','gender'=>'Gender','blood_group'=>'Blood group','current_address'=>'Current address','permanent_address'=>'Permanent address','city'=>'City','state'=>'State','country'=>'Country','pin_code'=>'Postal code','emergency_name'=>'Emergency contact','emergency_phone'=>'Emergency number','emergency_relationship'=>'Relationship']:['employee_code'=>'Employee ID','department_name'=>'Department','designation_name'=>'Designation','role_name'=>'Role','manager_name'=>'Reporting manager','joining_date'=>'Joining date','employment_type'=>'Employment type','employment_status'=>'Employment status','login_status'=>'Login access'];
if($tab==='employment'){$q=$pdo->prepare('SELECT name FROM users WHERE id=?');$q->execute([$employee['manager_id']]);$employee['manager_name']=$q->fetchColumn();$employee['login_status']=$employee['active']?'Enabled':'Disabled';}
?><section class="card"><dl class="details"><?php foreach($fields as $key=>$label):?><div><dt><?=$label?></dt><dd><?=h($employee[$key]?:'Not entered')?></dd></div><?php endforeach;?></dl><?php if($employee['import_notes']):?><p class="hint"><?=h($employee['import_notes'])?></p><?php endif;?></section>
<?php else:$documentEditing=false;require __DIR__.'/employee-documents.php';endif;?>
